traces.query:
PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Firewall_Edge ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?alarmLabel WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Router_Core ;
         rdfs:label ?alarmLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ?time
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?pattern .
  ?pattern net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?type ?severity ?device
WHERE {
  net:Incident_DDoS net:composedOf ?rootAlarm .
  FILTER NOT EXISTS {
    ?prevAlarm net:causallyLinkedTo ?rootAlarm .
  }
  ?rootAlarm net:alarmType ?type ;
             net:hasSeverity ?severity ;
             net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCause ?label WHERE {
  net:Alarm_WebTimeout net:causallyLinkedTo* ?rootCause .
  ?rootCause rdfs:label ?label .
  FILTER NOT EXISTS { ?other net:causallyLinkedTo ?rootCause }
}

PREFIX net: <http://example.org/network#>
SELECT ?causeAlarm ?causeType
WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?causeAlarm .
  ?causeAlarm net:alarmType ?causeType .
}

PREFIX net: <http://example.org/network#>

SELECT ?downstreamAlarm ?label
WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?downstreamAlarm .
  ?downstreamAlarm a net:Alarm ;
                   rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?intermediateAlarm ?type ?severity WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?intermediateAlarm .
  ?intermediateAlarm net:causallyLinkedTo+ net:Alarm_WebTimeout .
  FILTER(?intermediateAlarm != net:Alarm_FirewallSpike && ?intermediateAlarm != net:Alarm_WebTimeout)
  OPTIONAL { ?intermediateAlarm net:alarmType ?type . }
  OPTIONAL { ?intermediateAlarm net:hasSeverity ?severity . }
}

PREFIX net: <http://example.org/network#>

ASK {
  <http://example.org/network#Alarm_CPU> (net:causallyLinkedTo)* <http://example.org/network#Alarm_WebTimeout> .
}

PREFIX net: <http://example.org/network#>

ASK {
  <http://example.org/network#Alarm_Latency> (net:causallyLinkedTo)+ <http://example.org/network#Alarm_WebTimeout> .
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?device
WHERE {
  ?rootAlarm a net:Alarm .
  FILTER NOT EXISTS {
    ?anyAlarm net:causallyLinkedTo ?rootAlarm .
  }
  ?rootAlarm net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?direction WHERE {
  {
    net:Alarm_Latency net:causallyLinkedTo net:Alarm_PacketDrop .
    BIND("Latency causes PacketDrop" AS ?direction)
  } UNION {
    net:Alarm_PacketDrop net:causallyLinkedTo net:Alarm_Latency .
    BIND("PacketDrop causes Latency" AS ?direction)
  }
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm
WHERE {
  net:Alarm_PacketDrop net:correlatedWith ?alarm .
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>
SELECT ?interventionDevice ?deviceLabel WHERE {
  ?alarmA a net:Alarm ;
          net:affectsDevice ?interventionDevice ;
          net:causallyLinkedTo ?alarmB .
  ?alarmB net:affectsDevice net:Router_Core .
  FILTER NOT EXISTS {
    ?alarmPrev net:causallyLinkedTo ?alarmA .
  }
  OPTIONAL { ?interventionDevice rdfs:label ?deviceLabel . }
}

PREFIX net: <http://example.org/network#>
SELECT ?affectedAlarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?affectedAlarm .
  ?affectedAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?preventedAlarm ?label WHERE {
  ?cpuAlarm net:alarmType "CPU_OVERLOAD" .
  ?cpuAlarm net:causallyLinkedTo ?preventedAlarm .
  ?preventedAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(DISTINCT ?affectedAlarm) AS ?preventedAlarmsCount)
WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo ?affectedAlarm .
}

PREFIX net: <http://example.org/network#>

SELECT ?remainingAlarm ?type ?severity ?time
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
  FILTER(?alarm != net:Alarm_CPU)
  OPTIONAL { ?alarm net:alarmType ?type . }
  OPTIONAL { ?alarm net:hasSeverity ?severity . }
  OPTIONAL { ?alarm net:triggeredAt ?time . }
  FILTER NOT EXISTS {
    net:Alarm_CPU net:causallyLinkedTo ?alarm .
  }
}

PREFIX net: <http://example.org/network#>

ASK {
  net:Alarm_Latency net:causallyLinkedTo net:Alarm_WebTimeout .
}
